style.css:
@-moz-document domain("pinterest.com") {
/* Genel Arka Plan Rengi (Tüm Sayfa Siyah) */
  body {
    background-color: black !important;
  }

  /* Üst Çubuk (Profil Fotoğrafı Dahil) */
  .header, .header * {
    background-color: black !important;
    color: red !important;
  }

  /* Sağ Yan Çubuk */
  .rightColumn {
    background-color: black !important;
    color: red !important;
  }

  /* Yazılar ve Logolar (Kırmızı) */
  * {
    color: red !important;
  }

  /* Resimler ve Videolar (Normal Görünüm) */
  img, video {
    filter: none !important;
  }

  /* Kaydırma Çubuğu */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: black;
  }

  ::-webkit-scrollbar-thumb {
    background-color: red;
    border-radius: 10px;
    border: 2px solid black;
  }
}
